local __alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local __lookup={}
for __i=1,#__alphabet do
    __lookup[string.sub(__alphabet,__i,__i)]=__i-1
end

local function __decode(__data)
    local __out={}
    local __acc,__bits=0,0

    for __i=1,#__data do
        local __char=string.sub(__data,__i,__i)
        local __value=__lookup[__char]

        if __value~=nil then
            __acc=__acc*64+__value
            __bits=__bits+6

            if __bits>=8 then
                __bits=__bits-8
                local __byte=math.floor(__acc/(2^__bits))%256
                __out[#__out+1]=string.char(bit32.bxor(__byte,173))
                __acc=__acc%(2^__bits)
            end
        end
    end

    return table.concat(__out)
end

